// Logo mitra (Dinas Pendidikan, KUA, Puskesmas) untuk baris "Dipercaya
// oleh" di Beranda.jsx.
//
// Disimpan sebagai base64 LANGSUNG di file ini (bukan file gambar
// terpisah di folder public/), supaya logo selalu ikut ter-bundle
// bersama kode dan tidak pernah 404 gara-gara lupa taruh file, salah
// folder, salah huruf besar/kecil, atau lupa deploy ulang.
//
// Cara ganti logo di kemudian hari:
//   1. Siapkan file PNG/JPG logo baru.
//   2. Encode ke base64, misalnya lewat terminal:
//        base64 -w0 logo-baru.png > logo-baru.b64.txt
//   3. Tempel isinya menggantikan string di bawah (jaga format
//      "data:image/png;base64,...." atau "data:image/jpeg;base64,...."
//      sesuai jenis file aslinya).

export const LOGO_DINAS_PENDIDIKAN = 'data:image/png;base64,'

export const LOGO_KUA = 'data:image/png;base64,'

export const LOGO_PUSKESMAS = 'data:image/png;base64,'
